(() => {const texture=new Image();let ready=false;function draw(c,i,x,y,w,h){const sw=texture.width/4,sh=texture.height/3;c.drawImage(texture,i%4*sw,Math.floor(i/4)*sh,sw,sh,x,y,w,h)}window.drawTerrainTile=(c,x,y,seed)=>{if(!ready)return false;const code=((x*73856093)^(y*19349663)^seed)>>>0;draw(c,code%8,-.5,-.5,1,1);return true};window.drawWallTile=(c,x,y,seed)=>{if(!ready)return false;const code=((x*347)^(y*113)^seed)>>>0;draw(c,8+code%4,x,y,1,1);return true};texture.onload=()=>{ready=true;window.gameDebug?.render()};texture.src='assets/terrain-varied.png';})();
